"""Lecciones editoriales de escucha con comprensión objetiva y producción escrita."""
def make(slug,title,level,theme,lines,vocab,quiz,written):
    questions=[]
    for i,(prompt,right,a,b,why) in enumerate(quiz):
        options=[right,a,b];options=options[i:]+options[:i]
        questions.append(dict(prompt=prompt,options=options,answer=options.index(right),explanation=why))
    return dict(id=slug,title=title,level=level,theme=theme,minutes=12,icon='♫',description=f'Escucha una situación de {theme.lower()}, comprende sus detalles y escribe tu propia respuesta.',dialogue=[line.split(': ',1) for line in lines.split('|')],vocabulary=vocab,questions=questions,written_questions=written)

